const axios = require("axios");

async function invokeNyckelFunction(urlInput) {
  try {
    const response = await axios.post(
      "https://www.nyckel.com/v1/functions/o2f0jzcdyut2qxhu/invoke",
      {
        input: urlInput
      },
      {
        headers: {
          "Accept": "application/json, text/javascript, */*; q=0.01",
          "X-Requested-With": "XMLHttpRequest",
          "Content-Type": "application/json"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

invokeNyckelFunction("https://example.com") // Ganti dengan URL yang ingin Anda proses
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
